// Supabase Auth (GoTrue) of the LOCAL stack, for the findings of 21 §4, J3-A (column « Test »),
// G-1 point 3, EC-38, EC-41 and EC-50. The keys are those `supabase status` prints: development
// keys of the local stack, generated by the CLI, which open nothing but this stack. They are read
// from the CLI at run time, never from a `.env*` file, never written anywhere, and refused unless
// every URL is on the loopback.
import { execFileSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";

const REPOSITORY_ROOT = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../../../..",
);
const CLI_SCRIPT = path.join(
  REPOSITORY_ROOT,
  "node_modules/supabase/dist/supabase.js",
);

/** URL of the local API gateway (`[api] port` of supabase/config.toml). */
export const LOCAL_API_URL = "http://127.0.0.1:54321";

export type LocalAuthStack = {
  /** `http://127.0.0.1:54321`: what SUPABASE_URL is locally. */
  apiUrl: string;
  /** `<apiUrl>/auth/v1`. */
  authUrl: string;
  /** `sb_secret_…` of the local stack: what apps/api carries. */
  secretKey: string;
  /** `sb_publishable_…` of the local stack: what an attacker would use (G-1), in tests only. */
  publishableKey: string;
  /** Mailpit, where GoTrue's native e-mails would land if it ever sent one (EC-41). */
  mailpitUrl: string;
};

const MISSING_AUTH =
  "Supabase Auth locale injoignable : lancer `corepack pnpm exec supabase start` (GoTrue, Kong " +
  "et Mailpit compris), avec INFLUX_LOCAL_AUTH_SIGN_IN_LIMIT et INFLUX_LOCAL_AUTH_VERIFY_LIMIT " +
  "exportées comme en CI (21 EC-51). Les constats de GoTrue ne sont jamais sautés.";

function isLoopbackUrl(value: unknown): value is string {
  if (typeof value !== "string") {
    return false;
  }
  try {
    const url = new URL(value);
    return url.protocol === "http:" && url.hostname === "127.0.0.1";
  } catch {
    return false;
  }
}

function readStatus(): Record<string, unknown> {
  let output: string;
  try {
    output = execFileSync(
      process.execPath,
      [CLI_SCRIPT, "status", "--output", "json"],
      {
        cwd: REPOSITORY_ROOT,
        encoding: "utf8",
        // The CLI's own messages (update notice…) are not needed; its failure is reported below.
        stdio: ["ignore", "pipe", "ignore"],
        timeout: 60_000,
      },
    );
  } catch (error) {
    throw new Error(MISSING_AUTH, { cause: error });
  }
  const parsed: unknown = JSON.parse(output);
  if (typeof parsed !== "object" || parsed === null) {
    throw new Error(MISSING_AUTH);
  }
  return parsed as Record<string, unknown>;
}

let stack: LocalAuthStack | undefined;

/**
 * The local GoTrue, its keys and Mailpit, read once per process. Refuses anything that is not
 * the loopback, or keys of another form than the new API keys (`sb_secret_`, `sb_publishable_`).
 */
export function localAuthStack(): LocalAuthStack {
  if (stack !== undefined) {
    return stack;
  }
  const status = readStatus();
  const apiUrl = status.API_URL;
  const secretKey = status.SECRET_KEY;
  const publishableKey = status.PUBLISHABLE_KEY;
  const mailpitUrl = status.MAILPIT_URL ?? status.INBUCKET_URL;
  if (apiUrl !== LOCAL_API_URL || !isLoopbackUrl(mailpitUrl)) {
    throw new Error(
      `la pile Supabase n'est pas celle du poste (attendu ${LOCAL_API_URL} et Mailpit en boucle locale). ${MISSING_AUTH}`,
    );
  }
  if (
    typeof secretKey !== "string" ||
    !secretKey.startsWith("sb_secret_") ||
    typeof publishableKey !== "string" ||
    !publishableKey.startsWith("sb_publishable_")
  ) {
    throw new Error(
      "clés de la pile locale inattendues : `sb_secret_…` et `sb_publishable_…` attendues (21 J3-E, EC-46).",
    );
  }
  stack = {
    apiUrl,
    authUrl: `${apiUrl}/auth/v1`,
    secretKey,
    publishableKey,
    mailpitUrl,
  };
  return stack;
}

/** Fails with an explicit message when GoTrue or Mailpit does not answer (never skipped). */
export async function requireLocalAuth(): Promise<LocalAuthStack> {
  const local = localAuthStack();
  try {
    const [health, mailbox] = await Promise.all([
      fetch(`${local.authUrl}/health`, {
        headers: { apikey: local.publishableKey },
        signal: AbortSignal.timeout(5_000),
      }),
      fetch(`${local.mailpitUrl}/api/v1/messages?limit=1`, {
        signal: AbortSignal.timeout(5_000),
      }),
    ]);
    if (!health.ok || !mailbox.ok) {
      throw new Error(`GoTrue ${health.status}, Mailpit ${mailbox.status}`);
    }
  } catch (error) {
    throw new Error(MISSING_AUTH, { cause: error });
  }
  return local;
}

/** Number of messages Mailpit holds for an address (GoTrue's native sends land there locally). */
export async function mailpitMessagesTo(
  local: LocalAuthStack,
  address: string,
): Promise<number> {
  const query = encodeURIComponent(`to:"${address}"`);
  const response = await fetch(
    `${local.mailpitUrl}/api/v1/search?query=${query}`,
    { signal: AbortSignal.timeout(5_000) },
  );
  if (!response.ok) {
    throw new Error(`Mailpit search answered ${response.status}`);
  }
  const body = (await response.json()) as { messages_count?: number };
  if (typeof body.messages_count !== "number") {
    throw new Error("Mailpit search answered without messages_count");
  }
  return body.messages_count;
}

/** Total number of messages in Mailpit. */
export async function mailpitTotal(local: LocalAuthStack): Promise<number> {
  const response = await fetch(`${local.mailpitUrl}/api/v1/messages?limit=1`, {
    signal: AbortSignal.timeout(5_000),
  });
  if (!response.ok) {
    throw new Error(`Mailpit answered ${response.status}`);
  }
  const body = (await response.json()) as { total?: number };
  if (typeof body.total !== "number") {
    throw new Error("Mailpit answered without total");
  }
  return body.total;
}
